        line = normalize(lines[i])
        if not line:
            i += 1
            continue
        m = cand_re.match(line)
        if not m:
            i += 1
            continue
        num = m.group(1)
        maj = major(num)
        if num in seen:
            break
        if maj not in allowed:
            if seen and (maj in stop_set or (maj.isdigit() and int(maj) <= 2)):
                break
            i += 1
            continue
        block = [line]
        j = i + 1
        while j < len(lines):
            nxt = normalize(lines[j])
            if not nxt:
                block.append(nxt)
                j += 1
                continue
            mm = cand_re.match(nxt)
            if mm:
                num2 = mm.group(1)
                maj2 = major(num2)
                if num2 in seen:
                    break
                if maj2 in allowed:
                    break
                if seen and (maj2 in stop_set or (maj2.isdigit() and int(maj2) <= 2)):
                    break
            block.append(nxt)
            j += 1
        cands.append((num, block))
        seen.add(num)
        i = j
    return cands


def score_candidate(num, block, doc_year, is_8k):
    txt = ' '.join(block).lower()
    score = 0
    if any(t in txt for t in material_terms):
        score += 4
    if any(t in txt for t in fallback_terms):
        score += 1
    if doc_year and doc_year in txt:
        score += 2
    if 'incorporated by reference' in txt or 'incorporated herein by reference' in txt:
        if not (doc_year and doc_year in txt):
            score -= 3
    if '*' in block[0] and not is_8k:
        score -= 2
    if is_8k and major(num) in {'99','104'}:
        score += 1
    return score


def predict(doc):
    lines = Path(doc['doc_path']).read_text(errors='ignore').splitlines()
    start = start_idx(lines)
    is_8k = '_8K' in doc['doc_name'] or 'form 8-k' in Path(doc['doc_path']).read_text(errors='ignore').lower()
    allowed = {'3','4','5','10','99','104'} if is_8k else {'4','5','10'}
    stop_set = {'31','32','101'} | ({'99','104'} if not is_8k else set())
    cands = parse_candidates(lines, start, allowed, stop_set)
    doc_year = report_year(doc['doc_name'])
    best = ('none listed', -999, None)
    for num, block in cands:
        s = score_candidate(num, block, doc_year, is_8k)
        if s > best[1]:
            desc = block[1] if len(block) > 1 else ''
            best = (f'Exhibit {num}: {desc}'.strip(), s, num)
    return best[0] if best[1] > 0 else 'none listed'

correct = 0
errs = []
for d in manifest['documents']:
    pred = predict(d)
    gt = d.get('ground_truth')
    if gt is None:
        gt = 'None listed'
    if pred == gt:
        correct += 1
    else:
        errs.append((d['doc_name'], pred, gt))
print('accuracy', correct/len(manifest['documents']), correct, len(manifest['documents']))
for e in errs[:40]:
    print(e)
